const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const moods=[{id:'radieux',emoji:'🤩',label:'Radieux'},{id:'heureux',emoji:'😊',label:'Heureux'},{id:'calme',emoji:'😌',label:'Calme'},{id:'triste',emoji:'😔',label:'Triste'},{id:'difficile',emoji:'😣',label:'Difficile'}];
const te=new TextEncoder(),td=new TextDecoder();let key=null,state=null,selectedMood='calme',calendarDate=new Date(),selectedDate=null,idleTimer=null;
const emptyState=()=>({version:2,entries:[],goals:[],dailyMoods:{},settings:{autoLock:true}});
const b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))),unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function derive(p,salt){const base=await crypto.subtle.importKey('raw',te.encode(p),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function encrypt(data,k,salt){const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},k,te.encode(JSON.stringify(data)));return{format:'journal-novembre-v2',kdf:'PBKDF2-SHA256',iterations:310000,salt:b64(salt),iv:b64(iv),ciphertext:b64(cipher)}}
async function decrypt(vault,k){const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(vault.iv)},k,unb64(vault.ciphertext));return JSON.parse(td.decode(plain))}
const getVault=()=>{try{return JSON.parse(localStorage.getItem('jn-vault-v2'))}catch{return null}};
async function save(){if(!key||!state)return;const current=getVault(),salt=current?unb64(current.salt):crypto.getRandomValues(new Uint8Array(16));localStorage.setItem('jn-vault-v2',JSON.stringify(await encrypt(state,key,salt)))}
function setupLock(){const exists=!!getVault();$('#lockIntro').textContent=exists?'Entre ton mot de passe pour retrouver tes souvenirs.':'Crée un mot de passe pour protéger ton journal sur cet appareil.';$('#confirmLabel').classList.toggle('hidden',exists);$('#confirmPassword').classList.toggle('hidden',exists);$('#confirmPassword').required=!exists;$('#unlockButton').textContent=exists?'Déverrouiller':'Créer mon journal'}
$('#unlockForm').addEventListener('submit',async e=>{e.preventDefault();const p=$('#password').value,v=getVault();$('#lockError').textContent='';try{if(!v){if(p.length<8)throw Error('Utilise au moins 8 caractères.');if(p!==$('#confirmPassword').value)throw Error('Les mots de passe ne correspondent pas.');const salt=crypto.getRandomValues(new Uint8Array(16));key=await derive(p,salt);state=emptyState();localStorage.setItem('jn-vault-v2',JSON.stringify(await encrypt(state,key,salt)))}else{key=await derive(p,unb64(v.salt));state=await decrypt(v,key)}openApp()}catch(err){key=null;state=null;$('#lockError').textContent=v?'Mot de passe incorrect ou sauvegarde illisible.':err.message}});
$('#showPassword').onclick=()=>{$('#password').type=$('#password').type==='password'?'text':'password'};
function openApp(){$('#password').value='';$('#confirmPassword').value='';$('#lockScreen').classList.add('hidden');$('#app').classList.remove('hidden');calendarDate=new Date();selectedDate=isoDate(new Date());renderAll();resetIdle()}
function lock(){key=null;state=null;$('#app').classList.add('hidden');$('#lockScreen').classList.remove('hidden');setupLock();clearTimeout(idleTimer)}
function resetIdle(){clearTimeout(idleTimer);if(state?.settings.autoLock)idleTimer=setTimeout(lock,300000)}
['pointerdown','keydown','scroll'].forEach(ev=>addEventListener(ev,resetIdle,{passive:true}));$('#lockButton').onclick=lock;
const isoDate=d=>{const x=new Date(d);return`${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
const fmtDate=s=>new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(s+'T12:00:00'));
function renderMoodButtons(target,compact=false){target.innerHTML=moods.map(m=>`<button type="button" class="mood-button ${m.id===selectedMood?'selected':''}" data-mood="${m.id}"><span>${m.emoji}</span><small>${m.label}</small></button>`).join('');target.querySelectorAll('button').forEach(b=>b.onclick=()=>{selectedMood=b.dataset.mood;renderMoodButtons(target,compact);if(target.id==='moodPicker'){state.dailyMoods[isoDate(new Date())]=selectedMood;save();toast('Humeur enregistrée')}})}
function mood(id){return moods.find(m=>m.id===id)||moods[2]}
function switchView(name){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));const titles={today:'Bonjour 👋',calendar:'Mon calendrier',memories:'Mes souvenirs',stats:'Mes statistiques',goals:'Mes objectifs',settings:'Sécurité et sauvegarde'};$('#viewTitle').textContent=titles[name];$('.sidebar').classList.remove('open');if(name==='calendar')renderCalendar();if(name==='memories')renderEntries();if(name==='stats')renderStats();if(name==='goals')renderGoals()}
$$('#nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
function card(e){const m=mood(e.mood),photo=e.photo?`style="background-image:url('${e.photo}')"`:'';return`<article class="entry-card ${e.photo?'with-photo':''}" data-id="${e.id}" ${photo}><time>${m.emoji} ${fmtDate(e.date)}</time><h4>${escapeHtml(e.title)}</h4><p>${escapeHtml(e.content.slice(0,120))}${e.content.length>120?'…':''}</p><span class="tags">${(e.tags||[]).map(t=>'#'+escapeHtml(t)).join(' ')}</span></article>`}
const escapeHtml=s=>(s||'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function bindCards(){$$('.entry-card').forEach(c=>c.onclick=()=>openEntry(state.entries.find(e=>e.id===c.dataset.id)))}
function renderRecent(){const list=[...state.entries].sort((a,b)=>b.updatedAt-a.updatedAt).slice(0,6);$('#recentEntries').innerHTML=list.length?list.map(card).join(''):'<div class="empty">Ton premier souvenir commencera ici 🍂</div>';bindCards()}
function renderEntries(){const q=$('#searchInput').value.toLowerCase().trim(),mf=$('#moodFilter').value;const list=[...state.entries].filter(e=>(!mf||e.mood===mf)&&(!q||[e.title,e.content,...(e.tags||[])].join(' ').toLowerCase().includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||b.updatedAt-a.updatedAt);$('#allEntries').innerHTML=list.length?list.map(card).join(''):'<div class="empty">Aucun souvenir ne correspond à ta recherche.</div>';bindCards()}
function openEntry(e=null){selectedMood=e?.mood||state.dailyMoods[isoDate(new Date())]||'calme';$('#entryId').value=e?.id||'';$('#entryDate').value=e?.date||isoDate(new Date());$('#entryTitle').value=e?.title||'';$('#entryContent').value=e?.content||'';$('#entryTags').value=(e?.tags||[]).join(', ');$('#photoPreview').src=e?.photo||'';$('#photoPreview').classList.toggle('hidden',!e?.photo);$('#dialogTitle').textContent=e?'Modifier mon souvenir':'Écrire ma journée';$('#deleteEntry').classList.toggle('hidden',!e);renderMoodButtons($('#entryMood'),true);$('#entryDialog').showModal()}
$('#entryForm').addEventListener('submit',async e=>{e.preventDefault();const id=$('#entryId').value||crypto.randomUUID(),old=state.entries.find(x=>x.id===id);let photo=old?.photo||null,file=$('#entryPhoto').files[0];if(file){if(file.size>2_000_000)return toast('La photo dépasse 2 Mo');photo=await fileData(file)}const entry={id,date:$('#entryDate').value,title:$('#entryTitle').value.trim(),content:$('#entryContent').value.trim(),tags:$('#entryTags').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,12),mood:selectedMood,photo,createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};if(old)Object.assign(old,entry);else state.entries.push(entry);state.dailyMoods[entry.date]=entry.mood;await save();$('#entryDialog').close();$('#entryPhoto').value='';renderAll();toast('Souvenir enregistré')});
const fileData=f=>new Promise((res,rej)=>{const r=new FileReader;r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f)});$('#entryPhoto').onchange=async()=>{const f=$('#entryPhoto').files[0];if(f&&f.size<=2_000_000){$('#photoPreview').src=await fileData(f);$('#photoPreview').classList.remove('hidden')}};
$('#deleteEntry').onclick=async()=>{if(confirm('Supprimer définitivement ce souvenir ?')){state.entries=state.entries.filter(e=>e.id!==$('#entryId').value);await save();$('#entryDialog').close();renderAll();toast('Souvenir supprimé')}};$('#closeDialog').onclick=$('#cancelEntry').onclick=()=>$('#entryDialog').close();
function renderCalendar(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth();$('#calendarMonth').textContent=new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(calendarDate);const first=new Date(y,m,1),start=new Date(y,m,1-((first.getDay()+6)%7));let html='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const ds=isoDate(d),n=state.entries.filter(e=>e.date===ds).length;html+=`<button class="day ${d.getMonth()!==m?'other':''} ${ds===isoDate(new Date())?'today':''} ${ds===selectedDate?'selected':''} ${n?'has-entries':''}" data-date="${ds}" aria-label="${d.getDate()} : ${n} souvenir${n>1?'s':''}"><span>${d.getDate()}</span>${n?`<strong class="entry-count">${n}</strong>`:'<span class="no-entry"></span>'}</button>`}$('#calendarGrid').innerHTML=html;$$('.day').forEach(b=>b.onclick=()=>{selectedDate=b.dataset.date;renderCalendar();document.querySelector('#calendarEntries').scrollIntoView({behavior:'smooth',block:'start'})});renderCalendarEntries()}
function renderCalendarEntries(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),selected=state.entries.filter(e=>e.date===selectedDate),monthly=[...state.entries].filter(e=>{const d=new Date(e.date+'T12:00:00');return d.getFullYear()===y&&d.getMonth()===m}).sort((a,b)=>b.date.localeCompare(a.date));const showingSelected=selected.length>0;const list=showingSelected?selected:monthly;const title=showingSelected?fmtDate(selectedDate):`Souvenirs de ${new Intl.DateTimeFormat('fr-FR',{month:'long'}).format(calendarDate)}`;$('#calendarEntries').innerHTML=`<div class="section-head"><div><p class="eyebrow">${showingSelected?'JOUR SÉLECTIONNÉ':'TOUT LE MOIS'}</p><h3>${title}</h3></div><button class="primary" id="addSelected">+ Ajouter</button></div>`+(list.length?list.map(card).join(''):'<div class="empty">Aucun souvenir ce mois-ci. Les jours avec des souvenirs seront colorés ici.</div>');$('#addSelected').onclick=()=>{openEntry();$('#entryDate').value=selectedDate};bindCards()}
function renderStats(){const total=state.entries.length,days=new Set(state.entries.map(e=>e.date)).size,words=state.entries.reduce((n,e)=>n+e.content.split(/\s+/).filter(Boolean).length,0);$('#statCards').innerHTML=`<div class="stat"><strong>${total}</strong>souvenir${total!==1?'s':''}</div><div class="stat"><strong>${days}</strong>jour${days!==1?'s':''} raconté${days!==1?'s':''}</div><div class="stat"><strong>${words}</strong>mots déposés</div>`;const counts=Object.fromEntries(moods.map(m=>[m.id,0]));state.entries.forEach(e=>counts[e.mood]++);const max=Math.max(1,...Object.values(counts));$('#moodChart').innerHTML=moods.map(m=>`<div class="mood-row"><span>${m.emoji} ${m.label}</span><div class="bar"><i style="width:${counts[m.id]/max*100}%"></i></div><b>${counts[m.id]}</b></div>`).join('');const days7=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const ds=isoDate(d);days7.push({d,count:state.entries.filter(e=>e.date===ds).length})}const mx=Math.max(1,...days7.map(x=>x.count));$('#weekChart').innerHTML=days7.map(x=>`<div class="week-col"><i style="height:${Math.max(5,x.count/mx*170)}px"></i>${new Intl.DateTimeFormat('fr-FR',{weekday:'short'}).format(x.d)}<br><b>${x.count}</b></div>`).join('')}
function renderGoals(){$('#goalList').innerHTML=state.goals.length?state.goals.map(g=>`<div class="goal ${g.done?'done':''}" data-id="${g.id}"><input type="checkbox" ${g.done?'checked':''}><span>${escapeHtml(g.text)}</span><button>×</button></div>`).join(''):'<div class="empty">Ajoute un petit objectif qui te fait du bien.</div>';$$('.goal input').forEach(x=>x.onchange=async()=>{const g=state.goals.find(g=>g.id===x.parentElement.dataset.id);g.done=x.checked;await save();renderGoals()});$$('.goal button').forEach(x=>x.onclick=async()=>{state.goals=state.goals.filter(g=>g.id!==x.parentElement.dataset.id);await save();renderGoals()})}
$('#goalForm').onsubmit=async e=>{e.preventDefault();state.goals.push({id:crypto.randomUUID(),text:$('#goalText').value.trim(),done:false});$('#goalText').value='';await save();renderGoals()};$('#addGoal').onclick=()=>{$('#goalForm').classList.toggle('hidden');$('#goalText').focus()};
function renderAll(){const now=new Date();$('#dateLine').textContent=new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long'}).format(now).toUpperCase();selectedMood=state.dailyMoods[isoDate(now)]||'calme';renderMoodButtons($('#moodPicker'));renderRecent();renderCalendar();renderEntries();renderStats();renderGoals();$('#autoLockToggle').checked=state.settings.autoLock}
$('#newEntryHero').onclick=()=>openEntry();$('#seeAll').onclick=()=>switchView('memories');$('#quickSearch').onclick=()=>{switchView('memories');$('#searchInput').focus()};$('#searchInput').oninput=renderEntries;$('#moodFilter').innerHTML+ moods.map(m=>`<option value="${m.id}">${m.emoji} ${m.label}</option>`).join('');$('#moodFilter').onchange=renderEntries;$('#prevMonth').onclick=()=>{calendarDate.setMonth(calendarDate.getMonth()-1);renderCalendar()};$('#nextMonth').onclick=()=>{calendarDate.setMonth(calendarDate.getMonth()+1);renderCalendar()};$('#menuButton').onclick=()=>$('.sidebar').classList.toggle('open');
$('#autoLockToggle').onchange=async e=>{state.settings.autoLock=e.target.checked;await save();resetIdle();toast('Préférence enregistrée')};
$('#exportButton').onclick=()=>{const blob=new Blob([localStorage.getItem('jn-vault-v2')],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`journal-novembre-${isoDate(new Date())}.jnv2`;a.click();URL.revokeObjectURL(a.href);toast('Sauvegarde chiffrée exportée')};
$('#importInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const imported=JSON.parse(await f.text());if(imported.format!=='journal-novembre-v2'||!imported.ciphertext)throw Error();if(!confirm('Remplacer le journal actuel par cette sauvegarde chiffrée ?'))return;localStorage.setItem('jn-vault-v2',JSON.stringify(imported));toast('Sauvegarde importée — déverrouille-la');setTimeout(lock,700)}catch{toast('Fichier de sauvegarde invalide')}e.target.value=''};
$('#deleteVault').onclick=()=>{const check=prompt('Cette action est irréversible. Écris EFFACER pour confirmer.');if(check==='EFFACER'){localStorage.removeItem('jn-vault-v2');lock();toast('Journal effacé')}};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
setupLock();
